const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const mesquiteFlat = ee.Geometry.Point([-117.10, 36.57]); // Representative point in Mesquite Flat
  const panamintMountains = ee.Geometry.Point([-117.06, 36.26]); // Representative point in Panamint Mountains
  const startDate = '2013-06-30';
  const endDate = '2013-07-01'; // Single day

  // Define a small buffer around the points to get a region mean
  const bufferSize = 1000; // meters
  const mesquiteFlatBuffered = mesquiteFlat.buffer(bufferSize);
  const panamintMountainsBuffered = panamintMountains.buffer(bufferSize);

  // 2. Data Acquisition & Check
  let collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterDate(startDate, endDate)
    .filterBounds(mesquiteFlat.merge(panamintMountains)); // Filter by both locations to ensure coverage

  if (collection.size().getInfo() === 0) {
    console.log("No Landsat 8 images found for June 30, 2013, covering the specified locations.");
    console.log("C1");
    return;
  }

  // Get the first (and likely only) image for the date
  const image = ee.Image(collection.first());

  // Function to mask clouds and shadows from QA_PIXEL band of Landsat 8 SR
  // Also check ST_QA for valid LST measurements
  function maskL8Clouds(image) {
    const qaPixel = image.select('QA_PIXEL');
    const qaSt = image.select('ST_QA');

    // Bits 3 and 5 are cloud shadow and clouds, respectively.
    // Bits 7 and 9 are cirrus and snow/ice. For LST, clouds are the main concern.
    const cloudShadowBitMask = (1 << 3);
    const cloudsBitMask = (1 << 5);

    // Both flags should be set to zero, indicating clear conditions.
    const mask = qaPixel.bitwiseAnd(cloudShadowBitMask).eq(0)
      .and(qaPixel.bitwiseAnd(cloudsBitMask).eq(0));

    // ST_QA bit 7 is LST_VALID, should be 1 for valid LST
    const lstValidBitMask = (1 << 7);
    const stMask = qaSt.bitwiseAnd(lstValidBitMask).eq(lstValidBitMask); // Ensure this bit is set

    // Combine masks
    return image.updateMask(mask).updateMask(stMask);
  }

  // Apply cloud mask and select the Surface Temperature band (ST_B10)
  const maskedImage = maskL8Clouds(image);
  const lstBand = maskedImage.select('ST_B10');

  // Convert LST from Kelvin * 0.00341802 + 149.0 to Celsius
  const lstCelsius = lstBand.multiply(0.00341802).add(149.0).subtract(273.15); // Convert Kelvin to Celsius

  // Set scale for reduceRegion - use a higher scale for larger regions or to avoid memory errors
  const scale = 100; // Landsat native resolution is 30m, but LST is derived, 100m is safe

  // 3. Processing & Calculation
  const reduceProperties = {
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    scale: scale,
    maxPixels: 1e9
  };

  const mesquiteFlatStats = lstCelsius.reduceRegion({
    geometry: mesquiteFlatBuffered,
    ...reduceProperties
  });

  const panamintMountainsStats = lstCelsius.reduceRegion({
    geometry: panamintMountainsBuffered,
    ...reduceProperties
  });

  const mesquiteFlatLST = mesquiteFlatStats.get('ST_B10').getInfo();
  const mesquiteFlatPixels = mesquiteFlatStats.get('ST_B10_count').getInfo();
  const panamintMountainsLST = panamintMountainsStats.get('ST_B10').getInfo();
  const panamintMountainsPixels = panamintMountainsStats.get('ST_B10_count').getInfo();

  // 4. Validation & Final Answer
  console.log(`Mesquite Flat: LST = ${mesquiteFlatLST !== null ? mesquiteFlatLST.toFixed(2) + ' C' : 'N/A'}, Pixels = ${mesquiteFlatPixels}`);
  console.log(`Panamint Mountains: LST = ${panamintMountainsLST !== null ? panamintMountainsLST.toFixed(2) + ' C' : 'N/A'}, Pixels = ${panamintMountainsPixels}`);

  if (mesquiteFlatPixels === 0 || panamintMountainsPixels === 0) {
    console.log("No valid pixels remaining after masking for one or both locations.");
    console.log("C2");
    return;
  }

  if (mesquiteFlatLST === null || isNaN(mesquiteFlatLST) ||
      panamintMountainsLST === null || isNaN(panamintMountainsLST)) {
    console.log("Calculation resulted in invalid (null/NaN) LST for one or both locations.");
    console.log("C3");
    return;
  }

  // Compare the LST values
  if (mesquiteFlatLST > panamintMountainsLST) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
